.ds-record { display: grid; grid-template-columns: minmax(0, 1fr) 142px; column-gap: 20px; padding: 20px 0; border-bottom: 1px solid var(--color-rule, #dce3e3); }
.ds-record:first-child { padding-top: 0; }
.ds-record:last-child { border-bottom: 0; padding-bottom: 0; }
.ds-record h3 { font-size: 18px; }
.ds-record time { grid-column: 2; grid-row: 1 / 3; text-align: right; color: var(--color-muted, #596366); font-size: 13px; padding-top: 2px; font-variant-numeric: tabular-nums; }
.ds-record-subtitle { font-size: 15px; margin: 5px 0 3px; }
.ds-education-school { font-size: 14px; color: var(--color-muted, #596366); margin: 4px 0; }
.ds-education-degree { color: var(--color-accent, #215e68); font-weight: 500; }
.ds-education-lab { margin: 5px 0 0; }
.ds-record time { font-style: italic; }
.ds-record-detail { font-size: 14px; color: var(--color-muted, #596366); margin: 4px 0 0; line-height: 1.6; grid-column: 1 / -1; }
.ds-record-tag { font-size: 12px; margin-left: 7px; font-weight: 500; color: var(--color-accent, #215e68); }
.ds-record-highlights { padding-left: 18px; font-size: 14px; color: var(--color-muted, #596366); margin: 8px 0 0; }
.ds-record-highlights li { padding-left: 2px; margin: 3px 0; }
@media (max-width: 720px) { .ds-record { grid-template-columns: 1fr; gap: 0; padding: 22px 0; } .ds-record time { grid-column: 1; grid-row: auto; text-align: left; padding-top: 0; margin-bottom: 7px; order: -1; } .ds-record-detail { grid-column: 1; } }

